import { InvalidStateTransitionError } from "./errors";
import { OrderItem } from "./order-item";
import { OrderState, isCancellable, nextStateOf } from "./order-state";

export class Order {
  private currentState: OrderState = "placed";

  constructor(
    readonly id: string,
    readonly customerId: string,
    readonly items: readonly OrderItem[],
    readonly placedAt: Date,
  ) {}

  get state(): OrderState {
    return this.currentState;
  }

  advance(): void {
    const next = nextStateOf(this.currentState);
    if (next === undefined) {
      throw new InvalidStateTransitionError(`Order in state ${this.currentState} cannot advance`);
    }
    this.currentState = next;
  }

  cancel(): void {
    if (!isCancellable(this.currentState)) {
      throw new InvalidStateTransitionError(`Order in state ${this.currentState} cannot be cancelled`);
    }
    this.currentState = "cancelled";
  }
}

